:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  background-color: #0a0a1a;
  border: 2px solid var(--accent);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.overlay {
  position: absolute;
  inset: 0;
  background-color: rgba(10, 10, 26, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 16px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content h2 {
  font-size: 2rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.overlay-content p {
  font-size: 1.125rem;
  color: var(--text);
}

.hint {
  margin-top: 8px;
  font-size: 0.95rem;
  opacity: 0.8;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  background-color: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1.125rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, transform 0.1s;
  min-width: 120px;
}

button:hover {
  background-color: var(--primary);
  border-color: var(--text);
}

button:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
  background-color: #b8324a;
}

.how-to-play {
  background-color: rgba(15, 52, 96, 0.4);
  border-radius: 8px;
  padding: 16px;
  border-left: 4px solid var(--primary);
}

.how-to-play h2 {
  font-size: 1.25rem;
  margin-bottom: 8px;
  color: var(--primary);
}

.how-to-play ul {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.how-to-play li {
  font-size: 1rem;
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

kbd {
  background-color: var(--accent);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: monospace;
  font-size: 0.95rem;
  border: 1px solid var(--primary);
  display: inline-block;
  min-width: 24px;
  text-align: center;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  button {
    min-width: 100px;
    padding: 10px 16px;
    font-size: 1rem;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreSpan = document.getElementById('score');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayMessage = document.getElementById('overlayMessage');
  const overlayHint = document.getElementById('overlayHint');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;

  let snake = [];
  let direction = { x: 0, y: 0 };
  let nextDirection = { x: 0, y: 0 };
  let food = { x: 0, y: 0 };
  let score = 0;
  let gameState = 'paused'; // 'paused', 'running', 'gameover'
  let gameInterval = null;
  let speed = 150;

  function resetGame() {
    snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    scoreSpan.textContent = '0';
    gameState = 'paused';
    placeFood();
    updateOverlay('paused');
    updatePauseButton();
    clearInterval(gameInterval);
    gameInterval = null;
    draw();
  }

  function placeFood() {
    const freeCells = [];
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        if (!snake.some(seg => seg.x === x && seg.y === y)) {
          freeCells.push({ x, y });
        }
      }
    }
    if (freeCells.length === 0) {
      // Win condition, but we'll just keep game over
      gameOver(true);
      return;
    }
    food = freeCells[Math.floor(Math.random() * freeCells.length)];
  }

  function draw() {
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid lines (subtle)
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(canvas.width, i * CELL_SIZE);
      ctx.stroke();
    }

    // Draw food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

    // Draw snake
    snake.forEach((seg, index) => {
      ctx.fillStyle = index === 0 ? '#eaeaea' : '#0f3460';
      ctx.fillRect(seg.x * CELL_SIZE, seg.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      // Add a pixel highlight
      ctx.fillStyle = index === 0 ? '#ffffff' : '#1a4a7a';
      ctx.fillRect(seg.x * CELL_SIZE + 2, seg.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);
    });
  }

  function update() {
    if (gameState !== 'running') return;

    direction = { ...nextDirection };

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Wall collision
    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      gameOver();
      return;
    }

    // Self collision
    if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      scoreSpan.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function gameOver(win = false) {
    gameState = 'gameover';
    clearInterval(gameInterval);
    gameInterval = null;
    updateOverlay('gameover');
    updatePauseButton();
    draw();
  }

  function startGame() {
    if (gameState === 'gameover') {
      resetGame();
    }
    if (gameState === 'paused') {
      gameState = 'running';
      updateOverlay('running');
      updatePauseButton();
      clearInterval(gameInterval);
      gameInterval = setInterval(update, speed);
    }
  }

  function pauseGame() {
    if (gameState === 'running') {
      gameState = 'paused';
      clearInterval(gameInterval);
      gameInterval = null;
      updateOverlay('paused');
      updatePauseButton();
    }
  }

  function togglePause() {
    if (gameState === 'running') {
      pauseGame();
    } else if (gameState === 'paused') {
      startGame();
    } else if (gameState === 'gameover') {
      resetGame();
      startGame();
    }
  }

  function updateOverlay(state) {
    if (state === 'running') {
      overlay.classList.add('hidden');
    } else {
      overlay.classList.remove('hidden');
      if (state === 'paused') {
        overlayTitle.textContent = 'Paused';
        overlayMessage.textContent = 'Press Pause or Space to start.';
        overlayHint.textContent = 'Use arrow keys to move.';
      } else if (state === 'gameover') {
        overlayTitle.textContent = 'Game Over';
        overlayMessage.textContent = `Final Score: ${score}`;
        overlayHint.textContent = 'Press Restart or Space to play again.';
      }
    }
  }

  function updatePauseButton() {
    if (gameState === 'running') {
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    } else {
      pauseBtn.textContent = 'Resume';
      pauseBtn.setAttribute('aria-label', 'Resume game');
    }
  }

  // Event listeners
  window.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' ', 'p', 'P'].includes(key)) {
      e.preventDefault();
    }

    if (key === ' ' || key === 'p' || key === 'P') {
      togglePause();
      return;
    }

    if (gameState !== 'running') return;

    if (key === 'ArrowUp' && direction.y === 0) {
      nextDirection = { x: 0, y: -1 };
    } else if (key === 'ArrowDown' && direction.y === 0) {
      nextDirection = { x: 0, y: 1 };
    } else if (key === 'ArrowLeft' && direction.x === 0) {
      nextDirection = { x: -1, y: 0 };
    } else if (key === 'ArrowRight' && direction.x === 0) {
      nextDirection = { x: 1, y: 0 };
    }
  });

  pauseBtn.addEventListener('click', togglePause);

  restartBtn.addEventListener('click', () => {
    clearInterval(gameInterval);
    gameInterval = null;
    resetGame();
    draw();
  });

  // Initialize
  resetGame();
})();
